# Scaffold
############################################################
Scaffold::Begin(numbered => 1,is_open => "correct_or_first_incorrect",can_open => always,);

############################################################
# Section
############################################################
Section::Begin("");

BEGIN_PGML
Give three points which lie on the graph of [`T\text{,}`] separated by commas.

[_]{$evaluator}{10}

Which of the following statements is true about the graph of [`T(s)\text{?}`]

[_]{$radio}{5}

END_PGML

Section::End();

